{"module": "src/packages/agent/hooks.ts",
 "edits": [
  {"file": "src/packages/agent/hooks.ts",
   "old_string": "// @port-slot: processHookJSONOutput",
   "new_string": "/**
 * Traduce el JSON síncrono que un hook devuelve por stdout a un resultado
 * parcial del motor: decisión de permiso, bloqueo, contexto adicional y el
 * adjunto de conversación correspondiente. Porte de
 * `ccnmt: packages/agent/hooks.ts:656-923`.
 */
function processHookJSONOutput({
  json: rawJson,
  command,
  hookName,
  toolUseID,
  hookEvent,
  expectedHookEvent,
  stdout,
  stderr,
  exitCode,
  durationMs,
}: {
  json: SyncHookJSONOutput
  command: string
  hookName: string
  toolUseID: string
  hookEvent: HookEvent
  expectedHookEvent?: HookEvent
  stdout?: string
  stderr?: string
  exitCode?: number
  durationMs?: number
}) {
  // Tipado local: `SyncHookJSONOutput` es `Record<string, unknown>` porque el
  // JSON de un hook no tiene forma fija; aquí se acota a los campos que esta
  // función lee.
  type TypedSyncHookOutput = SyncHookJSONOutput & {
    continue?: boolean
    stopReason?: string
    decision?: 'approve' | 'block'
    reason?: string
    systemMessage?: string
    hookSpecificOutput?: {
      hookEventName?: string
      permissionDecision?: 'allow' | 'deny' | 'ask' | 'defer'
      permissionDecisionReason?: string
      updatedInput?: Record<string, unknown>
      additionalContext?: string
      initialUserMessage?: string
      watchPaths?: string[]
      updatedMCPToolOutput?: unknown
      retry?: boolean
      decision?: { behavior: 'allow'; updatedInput?: Record<string, unknown> } | { behavior: 'deny' }
      action?: string
      content?: unknown
    }
  }
  const json = rawJson as TypedSyncHookOutput
  const result: Partial<HookResult> & {
    systemMessage?: string
    watchPaths?: string[]
    initialUserMessage?: string
    elicitationResponse?: { action: string; content?: unknown }
    elicitationResultResponse?: { action: string; content?: unknown }
  } = {}

  if (json.continue === false) {
    result.preventContinuation = true
    if (json.stopReason) result.stopReason = json.stopReason
  }

  if (json.decision) {
    switch (json.decision) {
      case 'approve':
        result.permissionBehavior = 'allow'
        break
      case 'block':
        result.permissionBehavior = 'deny'
        result.blockingError = { blockingError: json.reason || 'Blocked by hook', command }
        break
      default:
        throw new Error(`Unknown hook decision type: ${json.decision}. Valid types are: approve, block`)
    }
  }

  if (json.systemMessage) result.systemMessage = json.systemMessage

  if (json.hookSpecificOutput?.hookEventName === 'PreToolUse' && json.hookSpecificOutput.permissionDecision) {
    switch (json.hookSpecificOutput.permissionDecision) {
      case 'allow':
        result.permissionBehavior = 'allow'
        break
      case 'deny':
        result.permissionBehavior = 'deny'
        result.blockingError = { blockingError: json.reason || 'Blocked by hook', command }
        break
      case 'ask':
        result.permissionBehavior = 'ask'
        break
      case 'defer':
        // Una decisión diferida sólo se honra en modo no interactivo
        // (-p/--print) para una llamada de herramienta única; aquí sólo se
        // registra, la supresión ocurre en el punto de llamada.
        result.permissionBehavior = 'defer'
        break
    }
  }
  if (result.permissionBehavior !== undefined && json.reason !== undefined) {
    result.hookPermissionDecisionReason = json.reason
  }

  if (json.hookSpecificOutput) {
    if (expectedHookEvent && json.hookSpecificOutput.hookEventName !== expectedHookEvent) {
      throw new Error(
        `Hook returned incorrect event name: expected '${expectedHookEvent}' but got '${json.hookSpecificOutput.hookEventName}'. Full stdout: ${jsonStringify(json, null, 2)}`,
      )
    }

    switch (json.hookSpecificOutput.hookEventName) {
      case 'PreToolUse':
        if (json.hookSpecificOutput.permissionDecision) {
          switch (json.hookSpecificOutput.permissionDecision) {
            case 'allow':
              result.permissionBehavior = 'allow'
              break
            case 'deny':
              result.permissionBehavior = 'deny'
              result.blockingError = {
                blockingError: json.hookSpecificOutput.permissionDecisionReason || json.reason || 'Blocked by hook',
                command,
              }
              break
            case 'ask':
              result.permissionBehavior = 'ask'
              break
            case 'defer':
              result.permissionBehavior = 'defer'
              break
          }
        }
        result.hookPermissionDecisionReason = json.hookSpecificOutput.permissionDecisionReason
        if (json.hookSpecificOutput.updatedInput) result.updatedInput = json.hookSpecificOutput.updatedInput
        result.additionalContext = json.hookSpecificOutput.additionalContext
        break
      case 'UserPromptSubmit':
        result.additionalContext = json.hookSpecificOutput.additionalContext
        break
      case 'SessionStart':
        result.additionalContext = json.hookSpecificOutput.additionalContext
        result.initialUserMessage = json.hookSpecificOutput.initialUserMessage
        if (json.hookSpecificOutput.watchPaths) result.watchPaths = json.hookSpecificOutput.watchPaths
        break
      case 'Setup':
        result.additionalContext = json.hookSpecificOutput.additionalContext
        break
      case 'SubagentStart':
        result.additionalContext = json.hookSpecificOutput.additionalContext
        break
      case 'PostToolUse':
        result.additionalContext = json.hookSpecificOutput.additionalContext
        if (json.hookSpecificOutput.updatedMCPToolOutput !== undefined) {
          result.updatedMCPToolOutput = json.hookSpecificOutput.updatedMCPToolOutput
        }
        break
      case 'PostToolUseFailure':
        result.additionalContext = json.hookSpecificOutput.additionalContext
        break
      case 'PostToolBatch':
        result.additionalContext = json.hookSpecificOutput.additionalContext
        break
      case 'UserPromptExpansion':
        result.additionalContext = json.hookSpecificOutput.additionalContext
        break
      case 'PermissionDenied':
        result.retry = json.hookSpecificOutput.retry
        break
      case 'PermissionRequest':
        if (json.hookSpecificOutput.decision) {
          result.permissionRequestResult = json.hookSpecificOutput.decision
          result.permissionBehavior = json.hookSpecificOutput.decision.behavior === 'allow' ? 'allow' : 'deny'
          if (json.hookSpecificOutput.decision.behavior === 'allow' && json.hookSpecificOutput.decision.updatedInput) {
            result.updatedInput = json.hookSpecificOutput.decision.updatedInput
          }
        }
        break
      case 'Elicitation':
        if (json.hookSpecificOutput.action) {
          result.elicitationResponse = {
            action: json.hookSpecificOutput.action,
            content: json.hookSpecificOutput.content,
          }
          if (json.hookSpecificOutput.action === 'decline') {
            result.blockingError = { blockingError: json.reason || 'Elicitation denied by hook', command }
          }
        }
        break
      case 'ElicitationResult':
        if (json.hookSpecificOutput.action) {
          result.elicitationResultResponse = {
            action: json.hookSpecificOutput.action,
            content: json.hookSpecificOutput.content,
          }
          if (json.hookSpecificOutput.action === 'decline') {
            result.blockingError = { blockingError: json.reason || 'Elicitation result blocked by hook', command }
          }
        }
        break
    }
  }

  return {
    ...result,
    message: result.blockingError
      ? attachment({ type: 'hook_blocking_error', hookName, toolUseID, hookEvent, blockingError: result.blockingError })
      : attachment({
          type: 'hook_success',
          hookName,
          toolUseID,
          hookEvent,
          content: '',
          stdout,
          stderr,
          exitCode,
          command,
          durationMs,
        }),
  }
}",
